// customers-pricing · кейс cp-07 (.qa/tests/customers-pricing/; обновлён 29.10 по #1c5a6c — у נציג есть «לקוח חדש») — права: נציג (משה כהן через «כניסה כעובד» — без клиентов;
// rep.json «testtest» — за ним закреплён клиент «test», 2026-10-04) и לקוח עסקי.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible();
  const row = page
    .locator('div')
    .filter({ hasText: employee })
    .filter({ has: page.getByRole('button', { name: 'פעולות' }) })
    .last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}

async function backToAdmin(page: Page) {
  await page.getByText('חזרה לחשבון הניהול').click();
  await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
}

test.describe('customers — נציג מכירות', () => {
  test.use({ storageState: auth('admin') });

  test('נציג בלי לקוחות משויכים: רשימה ריקה, יש «לקוח חדש» (#1c5a6c), כרטיס זר — «הלקוח לא נמצא.» #6a38cf5d #1c5a6c @desktop @prod-safe', async ({ page }) => {
    await page.goto('/customers');
    await expect(page.getByText(/^מציג \d+–\d+ מתוך \d+ תוצאות$/)).toBeVisible({ timeout: 20_000 });
    const firstRow = page.getByRole('main').getByRole('button').filter({ has: page.getByRole('button', { name: 'פעולות' }) }).first();
    await firstRow.locator('xpath=./*[1]').click();
    await expect(page).toHaveURL(/\/customers\/[0-9a-f-]{36}$/);
    const foreignCard = new URL(page.url()).pathname;

    await impersonate(page, 'משה כהן');
    try {
      await page.goto('/customers');
      await expect(page.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible();
      await expect(page.getByText('עדיין אין לקוחות עסקיים')).toBeVisible({ timeout: 20_000 });
      // #1c5a6c (29.10, просьба клиента): נציג сам добавляет клиентов — «לקוח חדש» есть, «ייבוא מאקסל» нет. Окно не открываем.
      await expect(page.getByRole('button', { name: 'לקוח חדש' })).toBeVisible();
      await expect(page.getByRole('button', { name: 'ייבוא מאקסל' })).toHaveCount(0);

      await page.goto(foreignCard);
      await expect(page.getByText('הלקוח לא נמצא.')).toBeVisible({ timeout: 20_000 });
      await expect(page.getByRole('button', { name: 'חזרה ללקוחות' })).toBeVisible();
    } finally {
      await page.goto('/customers');
      await backToAdmin(page);
    }
  });

  // За rep.json («testtest») закреплён клиент «test» (2026-10-04, .qa/context.md). Только чтение.
  test('נציג רואה רק לקוח שהוקצה לו, יש «לקוח חדש» בלי «ייבוא מאקסל», כרטיס לקוח אחר — «הלקוח לא נמצא.» #6a38cf5d #6fcb020f #1c5a6c @desktop @prod-safe', async ({ browser, page }) => {
    // чужой клиент: «פיצוציה בע'ם» (0531231234) — не закреплён за testtest
    await page.goto('/customers');
    await page.getByRole('main').getByText('0531231234').click();
    await expect(page).toHaveURL(/\/customers\/[0-9a-f-]{36}$/, { timeout: 20_000 });
    const foreignCard = new URL(page.url()).pathname;

    const ctx = await browser.newContext({ storageState: auth('rep'), baseURL: test.info().project.use.baseURL });
    const rep = await ctx.newPage();
    try {
      await rep.goto('/customers');
      await expect(rep.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible({ timeout: 20_000 });
      await expect(rep.getByText('מציג 1–1 מתוך תוצאה אחת')).toBeVisible({ timeout: 20_000 }); // #6fcb020f (было «1 תוצאות»)
      await expect(rep.getByRole('main').getByText('0531231235')).toBeVisible();
      await expect(rep.getByRole('main').getByText('0531231234')).toHaveCount(0);
      // #1c5a6c (29.10): у נציג есть «לקוח חדש», «ייבוא מאקסל» — нет. Окно не открываем (тест только читает).
      await expect(rep.getByRole('button', { name: 'לקוח חדש' })).toBeVisible();
      await expect(rep.getByRole('button', { name: 'ייבוא מאקסל' })).toHaveCount(0);

      await rep.getByRole('main').getByText('0531231235').click();
      await expect(rep).toHaveURL(/\/customers\/[0-9a-f-]{36}$/, { timeout: 20_000 });
      await expect(rep.getByText('הזמנות אחרונות')).toBeVisible({ timeout: 20_000 });
      await expect(rep.getByText(/^הזמנה #\d+$/).first()).toBeVisible();

      await rep.goto(foreignCard);
      await expect(rep.getByText('הלקוח לא נמצא.')).toBeVisible({ timeout: 20_000 });
    } finally {
      await ctx.close();
    }
  });
});

test.describe('customers / pricing — לקוח עסקי', () => {
  test.use({ storageState: auth('buyer') });
  for (const url of ['/customers', '/pricing/groups', '/pricing/customer', '/pricing/discounts']) {
    test(`לקוח לא נכנס ל-${url} — הפניה ל-/shop #6a38cf5d #6a38cf59 #6a38cf58 @desktop @prod-safe`, async ({ page }) => {
      await page.goto(url);
      await expect(page).toHaveURL(/\/shop$/, { timeout: 20_000 });
      await expect(page.getByRole('searchbox', { name: 'חיפוש מוצר' })).toBeVisible();
      await expect(page.getByRole('heading', { name: /^(לקוחות|קבוצות מוצרים|תמחור פר-לקוח|מחירונים והנחות)$/ })).toHaveCount(0);
    });
  }
});
